generation_rounds.planner_raw:
{
  "strategy": "Localize the geometry diagram interval, retrieve a small set of frames from that interval, and use OCR to read the visible numeric labels needed to compute the hypotenuse. If the labels are not fully readable via OCR alone, use chart/diagram interpretation on the same frames to recover the triangle measurements and angle-bisector context.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "temporal_grounder",
      "arguments": {
        "video_path": "VIDEO",
        "query": "geometry diagram showing a right triangle labeled A B C with point Q on hypotenuse AC and text indicating angle BAQ equals angle QAC"
      },
      "purpose": "Find the bounded interval where the answer-critical triangle diagram is on screen before reading measurements.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "VIDEO",
        "query": null,
        "timestamps": [
          "<STEP_1:segments[0].start>",
          "<STEP_1:segments[0].end>",
          "<STEP_1:segments[1].start>"
        ],
        "num_frames": 3
      },
      "purpose": "Sample candidate frames from likely diagram intervals to capture a clear, fully rendered state of the triangle with all side-length labels visible.",
      "depends_on": [
        1
      ]
    },
    {
      "step": 3,
      "tool": "ocr",
      "arguments": {
        "frame_path": "<STEP_2:frames>",
        "timestamp": null
      },
      "purpose": "Read the on-screen text and numeric side labels from the candidate diagram frames.",
      "depends_on": [
        2
      ]
    },
    {
      "step": 4,
      "tool": "chart_analyzer",
      "arguments": {
        "frame_path": "<STEP_2:frames>",
        "timestamp": null,
        "query": "geometry diagram of a right triangle: identify the visible side-length labels, which side is the hypotenuse, and any segment lengths or angle-bisector markings shown"
      },
      "purpose": "Interpret the structured geometry figure in case OCR alone does not clearly map numbers to the correct triangle sides.",
      "depends_on": [
        2
      ]
    }
  ],
  "refinement_instructions": "Build the trace from scratch. First identify, from the retrieved frame-level evidence, the frame that clearly shows the full triangle and all relevant labels; do not assume the first retrieved frame is the correct one unless its timestamp and visibility justify it. Use OCR detections to cite exact visible numbers/text, and use chart_analyzer frame_results to map those numbers to the correct sides and confirm which side is the hypotenuse. Then compute the hypotenuse from the grounded measurements or, if the hypotenuse value is directly labeled, match that grounded value to the closest exact option. Preserve tool provenance explicitly in the rewritten trace (e.g., OCR reads ..., chart_analyzer identifies ...). If OCR and chart_analyzer disagree, prefer the frame-level result from the clearest frame and explain the mapping. Update the final answer to the option supported by the verified diagram evidence; do not guess from the options without grounded numeric labels."
}
